#include <deque>
#include <iostream>

int main() {
    std::deque<int> d = {1, 2};
    d.pop_front(); 
    d.pop_back();

    // Check required precondition
    if (!d.empty()) {
        d.pop_front();
    } else {
        std::cerr << "Error: Attempted pop on empty container.\n";
        // Calling d.pop_front() here results in UB
    }
}
